def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full-width/full-height separator lines sharing one color.
    row_lines = {r: grid[r][0] for r in range(h)
                 if all(v == grid[r][0] for v in grid[r])}
    col_lines = {c: grid[0][c] for c in range(w)
                 if all(grid[r][c] == grid[0][c] for r in range(h))}
    shared = [color for color in set(row_lines.values()) & set(col_lines.values())
              if any(v == color for v in row_lines.values())
              and any(v == color for v in col_lines.values())]
    if not shared:
        return [row[:] for row in grid]
    # The cross/lines use the separator color; select the most frequent other color as background.
    sep = shared[0]
    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    rb = [-1] + [r for r, color in row_lines.items() if color == sep] + [h]
    cb = [-1] + [c for c, color in col_lines.items() if color == sep] + [w]
    row_bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    col_bands = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    # Use the occupied tile as a template and repeat it in each equal-sized tile.
    template = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            cells = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            if any(v != bg and v != sep for row in cells for v in row):
                template = cells
                break
        if template is not None:
            break
    if template is None:
        return [row[:] for row in grid]
    th, tw = len(template), len(template[0])
    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if r1 - r0 != th or c1 - c0 != tw:
                continue
            for dr in range(th):
                for dc in range(tw):
                    if template[dr][dc] != bg and template[dr][dc] != sep:
                        out[r0 + dr][c0 + dc] = template[dr][dc]
    return out

